 10	// Bipolar BNC volts from an ADC reading: the OPA2277 front-end maps ±10 V at
 11	// the BNC to 0..3.3 V at the ADC with midscale = 0 V (nominal; per-board
 12	// calibration is F2). Shared by GET_ANALOG_IN and the Mode 4 loop so both
 13	// report the same volts for the same counts.
 14	static inline float ainVoltsFromRaw(int raw) {
 15	  float frac = (float)raw / (float)adc_full_scale_counts;  // 0..1
 16	  return (frac - 0.5f) * 2.0f * mode4_ain_input_range_volts;
 17	}
