1566	void CommandProcessor::serviceOpenLoop() {
1567	  if (frame_rate_hz_ == 0 || frame_count_ <= 1) return;  // static frame
1568	  uint32_t rate_hz   = (frame_rate_hz_ < 0) ? (uint32_t)(-frame_rate_hz_)
1569	                                             : (uint32_t)frame_rate_hz_;
1570	  uint32_t period_us = microseconds_per_second / rate_hz;
1571	  uint32_t now = micros();
1572	  if ((now - last_advance_us_) < period_us) return;
1573	
1574	  // Advance by however many whole periods have elapsed (catch up if the loop
1575	  // was busy), then load the new frame once.
1576	  uint16_t steps = 0;
1577	  while ((now - last_advance_us_) >= period_us) {
1578	    last_advance_us_ += period_us;
1579	    if (++steps >= frame_count_) { steps = frame_count_; break; }  // clamp
1580	  }
1581	  int32_t idx = (int32_t)cur_frame_index_
1582	                + (frame_rate_hz_ > 0 ? (int32_t)steps : -(int32_t)steps);
1583	  idx %= (int32_t)frame_count_;
1584	  if (idx < 0) idx += (int32_t)frame_count_;
1585	  cur_frame_index_ = (uint16_t)idx;
1586	  loadFrame(cur_frame_index_);
1587	}
