1626	void CommandProcessor::ainCalLoad() {
1627	  AinCalRecord r;
1628	  EEPROM.get(ai_cal_eeprom_addr, r);
1629	  const size_t body = sizeof(AinCalRecord) - sizeof(uint16_t);
1630	  bool ok = memcmp(r.magic, "AIC1", 4) == 0 && r.version == ai_cal_record_version &&
1631	            r.crc == ainCalCrc(&r, body);
1632	  if (ok && r.adc_bits != adc_resolution_bits) {
1633	    // Points were taken at another raw scale (F1 moved 10 → 12 bit): the mV
1634	    // math would be wrong, so drop the points but keep the deadbands.
1635	    DBG_PRINTF("[ain] cal record is %u-bit, firmware is %u-bit — points discarded\n",
1636	               (unsigned)r.adc_bits, (unsigned)adc_resolution_bits);
1637	    for (int i = 0; i < 2; ++i) r.ch[i].valid = 0;
1638	    r.adc_bits = adc_resolution_bits;
1639	  }
1640	  if (ok) {
1641	    ain_cal_ = r;
1642	    ain_cal_source_ = ai_cal_source_eeprom;
1643	    ain_cal_mirror_ok_ = false;  // unknown until the next save
1644	    DBG_PRINTF("[ain] cal loaded: ch1 valid=%u open=%u gnd=%u db=%u | ch2 valid=%u open=%u gnd=%u db=%u\n",
1645	               (unsigned)r.ch[0].valid, (unsigned)r.ch[0].raw_open, (unsigned)r.ch[0].raw_gnd,
1646	               (unsigned)r.ch[0].deadband_mv, (unsigned)r.ch[1].valid, (unsigned)r.ch[1].raw_open,
1647	               (unsigned)r.ch[1].raw_gnd, (unsigned)r.ch[1].deadband_mv);
1648	  } else {
1649	    ainCalDefaults();
1650	    DBG_PRINTF("[ain] no calibration record in EEPROM — nominal ±10 V scale\n");
1651	  }
1652	}
