1667	bool CommandProcessor::ainCalMirrorSd() {
1668	  // Write-only JSON mirror for humans and the data record; never read back.
1669	  if (!sd_.available()) return false;
1670	  SD.mkdir(ai_cal_sd_dir);
1671	  SD.remove(ai_cal_sd_path);
1672	  File f = SD.open(ai_cal_sd_path, FILE_WRITE);
1673	  if (!f) return false;
1674	  f.printf("{\"version\":%u,\"adc_bits\":%u,\"ref_mv\":%u,\"channels\":[",
1675	           (unsigned)ain_cal_.version, (unsigned)ain_cal_.adc_bits, (unsigned)ai_cal_ref_mv);
1676	  for (int i = 0; i < 2; ++i) {
1677	    const AinCalChannel &c = ain_cal_.ch[i];
1678	    f.printf("%s{\"ch\":%d,\"valid\":%u,\"raw_open\":%u,\"raw_gnd\":%u,\"deadband_mv\":%u}",
1679	             i ? "," : "", i + 1, (unsigned)c.valid, (unsigned)c.raw_open, (unsigned)c.raw_gnd,
1680	             (unsigned)c.deadband_mv);
1681	  }
1682	  f.printf("]}\n");
1683	  f.close();
1684	  return true;
1685	}
