1695	uint16_t CommandProcessor::ainSampleRawAveraged(uint8_t pin, uint16_t n) const {
1696	  uint32_t acc = 0;
1697	  for (uint16_t i = 0; i < n; ++i) acc += (uint32_t)analogRead(pin);
1698	  return (uint16_t)((acc + n / 2) / n);
1699	}
