1701	float CommandProcessor::ainMv(uint8_t ch, int raw) const {
1702	  const AinCalChannel &c = ain_cal_.ch[(ch == 2) ? 1 : 0];
1703	  if (c.valid) {
1704	    // Two-point line through (raw_gnd, 0 mV) and (raw_open, +10 000 mV).
1705	    float a = (float)ai_cal_ref_mv / (float)(c.raw_open - c.raw_gnd);
1706	    return a * ((float)raw - (float)c.raw_gnd);
1707	  }
1708	  return ainVoltsFromRaw(raw) * 1000.0f;  // nominal ±10 V scale
1709	}
