1735	void CommandProcessor::serviceClosedLoop() {
1736	  if (frame_count_ == 0) return;
1737	  uint32_t sample_period_us = microseconds_per_second / mode4_sample_rate_hz;
1738	  uint32_t now = micros();
1739	  if ((now - last_sample_us_) < sample_period_us) return;
1740	
1741	  uint32_t dt_us = now - last_sample_us_;
1742	  last_sample_us_ = now;
1743	
1744	  // Bipolar BNC input volts (ainVoltsFromRaw; per-board calibration is F2),
1745	  // smoothed with the G3-style EWMA so one noisy conversion cannot step a
1746	  // frame. The first sample after trial start seeds the filter.
1747	  float v_raw = ainMv(1, analogRead(mode4_ain_pin)) / 1000.0f;  // calibrated when a record exists
1748	  if (!ain_filter_primed_) {
1749	    ain_filtered_v_ = v_raw;
1750	    ain_filter_primed_ = true;
1751	  } else {
1752	    ain_filtered_v_ += mode4_ain_filter_alpha * (v_raw - ain_filtered_v_);
1753	  }
1754	  // Deadband (F2): a static input a few mV off the calibrated zero must not
1755	  // creep the pattern — |v| below the channel's deadband counts as 0 fps.
1756	  float v_eff = (fabsf(ain_filtered_v_) * 1000.0f < (float)ain_cal_.ch[0].deadband_mv)
1757	                    ? 0.0f
1758	                    : ain_filtered_v_;
1759	  // G3-faithful coupling: fps = V * 100 fps/V * (gain / 10); gain 10 = unity,
1760	  // gain 2..5 = the everyday 20..50 fps/V (constants.h § Mode 4).
1761	  float fps = v_eff * mode4_unity_fps_per_volt * ((float)gain_ / 10.0f);
1762	  frame_accum_ += fps * ((float)dt_us / (float)microseconds_per_second);
1763	
1764	  bool changed = false;
1765	  while (frame_accum_ >= 1.0f) {
1766	    frame_accum_ -= 1.0f;
1767	    cur_frame_index_ = (uint16_t)((cur_frame_index_ + 1) % frame_count_);
1768	    changed = true;
1769	  }
1770	  while (frame_accum_ <= -1.0f) {
1771	    frame_accum_ += 1.0f;
1772	    cur_frame_index_ =
1773	        (uint16_t)((cur_frame_index_ + frame_count_ - 1) % frame_count_);
1774	    changed = true;
1775	  }
1776	  if (changed) loadFrame(cur_frame_index_);
1777	}
