 5	// CRC primitives used by the G6 pattern-file reader.
 6	//   - CRC-8/AUTOSAR : pattern-file header byte 17 (over header bytes 0-16)
 7	//   - CRC-16/CCITT  : per-frame trailer (over {FR magic, frame index, blocks})
 8	// Parameters and test vectors per g6_01-panel-protocol.md § CRC-8 algorithm
 9	// and g6_04-pattern-file-format.md § Per-frame CRC-16.
10	namespace G6 {
11	
12	// CRC-8/AUTOSAR: poly 0x2F, init 0xFF, refin=false, refout=false, xorout 0xFF.
13	// Universal check value 0xDF over the ASCII string "123456789".
14	inline uint8_t crc8_autosar(const uint8_t *data, size_t len) {
15	  uint8_t crc = 0xFF;
16	  for (size_t i = 0; i < len; ++i) {
17	    crc ^= data[i];
18	    for (uint8_t bit = 0; bit < 8; ++bit) {
19	      crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ 0x2F) : (uint8_t)(crc << 1);
20	    }
21	  }
22	  return crc ^ 0xFF;
23	}
24	
25	// CRC-16/CCITT-FALSE: poly 0x1021, init 0xFFFF, refin=false, refout=false,
26	// xorout 0x0000. Universal check value 0x29B1 over the ASCII string
27	// "123456789".
28	inline uint16_t crc16_ccitt_false(const uint8_t *data, size_t len) {
29	  uint16_t crc = 0xFFFF;
30	  for (size_t i = 0; i < len; ++i) {
31	    crc ^= (uint16_t)data[i] << 8;
32	    for (uint8_t bit = 0; bit < 8; ++bit) {
33	      crc = (crc & 0x8000) ? (uint16_t)((crc << 1) ^ 0x1021) : (uint16_t)(crc << 1);
34	    }
35	  }
36	  return crc;
37	}
