1456	// serviceUpload — one SET_PATTERN_FILE (0x85) chunk per loop() call.
1457	//
1458	// Mirrors serviceDownload() above (issue #16): reads+writes one ~4 KB chunk
1459	// per call instead of blocking inside processCommand() for the whole
1460	// transfer, and ul_deadline_ resets on every chunk actually read off the
1461	// wire rather than staying fixed from the start, so a slow-but-progressing
1462	// host doesn't trip the idle ceiling just because the transfer runs long.
1463	//
1464	// Unlike the download side, a failure here (idle timeout or SD write error)
1465	// doesn't mean the transfer can just stop: the host already committed to
1466	// sending total_len bytes, and whatever it hasn't sent yet will still land
1467	// on the wire and get misparsed as a bogus command unless something reads
1468	// and discards it first. ul_phase_'s kDraining value is that second phase:
1469	// same chunked service loop, just discarding instead of writing, with its
1470	// own bound (kUploadDrainTimeoutMs) since by then the transfer is already a
1471	// lost cause and this is purely resync, not recovery. See the ul_* fields'
1472	// comment in CommandProcessor.h (PR #27 review point 3) for why this is an
1473	// explicit phase transition rather than a bool checked at two sites: an
1474	// earlier version of this function used the latter and, on the FIRST
1475	// write-phase timeout, fell straight into the same "give up" response this
1476	// function now only reaches on a SECOND (drain-phase) timeout, never
1477	// reading the bytes still in flight, so they landed on the wire and got
1478	// misparsed as bogus commands once the source was freed up.
1479	// ---------------------------------------------------------------------------
1480	void CommandProcessor::serviceUpload() {
1481	  if (!ul_active_) return;
1482	
1483	  if (ul_phase_ == UploadPhase::kWriting) {
1484	    if ((int32_t)(millis() - ul_deadline_) >= 0) {
1485	      // First (write-phase) timeout: transition into draining instead of
1486	      // finalizing here. ul_drain_deadline_ is an absolute cap from now,
1487	      // not idle-reset; see the field comment in CommandProcessor.h.
1488	      ul_file_.close();
1489	      SD.remove(ul_path_);
1490	      ul_fail_status_ = 1;
1491	      strncpy(ul_fail_msg_, "Upload timeout", sizeof(ul_fail_msg_) - 1);
1492	      ul_phase_ = UploadPhase::kDraining;
1493	      ul_drain_deadline_ = millis() + kUploadDrainTimeoutMs;
1494	      return;
1495	    }
1496	  } else {  // kDraining
1497	    if ((int32_t)(millis() - ul_drain_deadline_) >= 0) {
1498	      // Draining also timed out — give up on resync too; the next framed
1499	      // byte the parser sees may be garbage, but continuing to wait
1500	      // indefinitely isn't better.
1501	      ul_source_->sendResponse(SET_PATTERN_FILE_CMD, ul_fail_status_, ul_fail_msg_);
1502	      ul_active_ = false;
1503	      ul_source_->commandConsumed();
1504	      return;
1505	    }
1506	  }
1507	
1508	  static uint8_t chunk[4096];
1509	  size_t want = (ul_remaining_ < sizeof(chunk)) ? (size_t)ul_remaining_ : sizeof(chunk);
1510	  size_t got = ul_source_->readBulkBytes(chunk, want);
1511	  if (got == 0) return;  // nothing new this tick; the checks above cover staleness
1512	
1513	  if (ul_phase_ == UploadPhase::kWriting) {
1514	    size_t written = ul_file_.write(chunk, got);
1515	    if (written != got) {
1516	      ul_file_.close();
1517	      SD.remove(ul_path_);
1518	      ul_fail_status_ = 1;
1519	      strncpy(ul_fail_msg_, "SD write error (card full?)", sizeof(ul_fail_msg_) - 1);
1520	      ul_phase_ = UploadPhase::kDraining;
1521	      ul_drain_deadline_ = millis() + kUploadDrainTimeoutMs;
1522	    }
1523	  }
1524	  ul_remaining_ -= (uint32_t)got;
1525	  // kDraining's deadline is an absolute cap set once above, not reset here.
1526	  if (ul_phase_ == UploadPhase::kWriting) {
1527	    ul_deadline_ = millis() + kUploadIdleTimeoutMs;
1528	  }
1529	
1530	  if (ul_remaining_ == 0) {
1531	    switch (ul_phase_) {
1532	      case UploadPhase::kDraining:
1533	        ul_source_->sendResponse(SET_PATTERN_FILE_CMD, ul_fail_status_, ul_fail_msg_);
1534	        break;
1535	      case UploadPhase::kWriting: {
1536	        uint32_t elapsed_ms = millis() - ul_start_ms_;
1537	        uint32_t kbps = elapsed_ms > 0 ? (uint32_t)(ul_total_ / elapsed_ms) : 0;
1538	        DBG_PRINTF("[cmd] set-pattern-file idx=%u wrote %lu bytes in %lu ms (%lu kB/s) to %s\n",
1539	                   (unsigned)ul_idx_, (unsigned long)ul_total_,
1540	                   (unsigned long)elapsed_ms, (unsigned long)kbps, ul_path_);
1541	        ul_file_.close();
1542	        ul_source_->sendResponse(SET_PATTERN_FILE_CMD, 0, "");
1543	        break;
1544	      }
1545	    }
1546	    ul_active_ = false;
1547	    ul_source_->commandConsumed();
1548	  }
1549	}
