1551	// Teardown for an upload whose owning source disconnected (PR #27 review
1552	// point 5), distinct from serviceUpload()'s own timeout/error paths: those
1553	// still expect the host to resume (kWriting -> kDraining) or have already
1554	// finished, so they respond and consume normally. A disconnected source has
1555	// nothing left to respond to and nothing left to resync, so this always
1556	// deletes the partial file and fully deactivates in one step; there's no
1557	// draining phase to enter since no more bytes will ever arrive on this
1558	// connection.
1559	void CommandProcessor::abortUpload() {
1560	  ul_file_.close();
1561	  SD.remove(ul_path_);
1562	  ul_active_ = false;
1563	  ul_source_->commandConsumed();
1564	}
