1097	//   param[5:6]  init_pos    uint16 LE  (initial frame index, 0-based)
1098	//   param[7:8]  gain        int16 LE  (Mode 4 velocity scaling, 10x fps/V)
1099	//   param[9:10] duration    uint16 LE  (AC::constants::duration_tick_ms ticks;
1100	//                                       0 = no controller-run auto-stop)
1101	//   param[11]   duty        uint8: 0 = pattern's stored duty_cycle (default —
1102	//                           and what messages that omit this byte already
1103	//                           mean), 1-255 = display every frame of THIS trial
1104	//                           at this duty (issue #33; transmit-time only, SD
1105	//                           untouched)
