1113	  // an SD read, mid-transfer of an unrelated dl_/ul_/ar_ operation. Same
1114	  // reasoning as the ALL_ON guard above: not corrupting (SD is SDIO, and
1115	  // loop() is single-threaded so accesses are naturally serialized), but
1116	  // confusing to have the display change while an SD transfer is still in
1117	  // flight, so refuse it rather than let it interleave.
1118	  if (dl_active_ || ul_active_ || ar_active_) {
1119	    current_source_->sendResponse(TRIAL_PARAMS_CMD, 1, "SD transfer in progress");
1120	    return;
1121	  }
1122	
1123	  const uint8_t *p = cmd.data + 2;          // first param byte
1124	  uint8_t param_len = cmd.data[0] - 1;       // claimed_len minus the cmd byte
1125	  if (param_len < 11) {
1126	    showError(CE_BAD_PAYLOAD_LEN);
1127	    current_source_->sendResponse(TRIAL_PARAMS_CMD, 1, "TRIAL_PARAMS too short");
1128	    return;
1129	  }
1130	
1131	  uint8_t  mode       = p[0];
1132	  uint16_t pattern_id = (uint16_t)p[1] | ((uint16_t)p[2] << 8);
1133	  int16_t  frame_rate = (int16_t)((uint16_t)p[3] | ((uint16_t)p[4] << 8));
1134	  uint16_t init_pos   = (uint16_t)p[5] | ((uint16_t)p[6] << 8);
1135	  int16_t  gain       = (int16_t)((uint16_t)p[7] | ((uint16_t)p[8] << 8));
1136	  uint16_t duration   = (uint16_t)p[9] | ((uint16_t)p[10] << 8);
1137	  // Absent field (message omits the byte) == 0 == stored duty.
1138	  uint8_t  duty       = (param_len >= 12) ? p[11] : 0;
1139	
1140	  ArenaState target;
1141	  switch (mode) {
1142	    case display_mode_open_loop:   target = ArenaState::OPEN_LOOP;   break;
1143	    case display_mode_show_frame:  target = ArenaState::SHOW_FRAME;  break;
1144	    case display_mode_closed_loop: target = ArenaState::CLOSED_LOOP; break;
1145	    default:
1146	      showError(CE_BAD_PARAM);
1147	      current_source_->sendResponse(TRIAL_PARAMS_CMD, 1,
1148	                        "TRIAL_PARAMS: mode must be 2/3/4");
1149	      return;
1150	  }
1151	
1152	  trial_duty_ = duty;  // set BEFORE enterPatternMode — loadFrame() applies it
1153	
1154	  if (enterPatternMode(target, pattern_id, frame_rate, gain, init_pos, duration)) {
1155	    current_source_->sendResponse(TRIAL_PARAMS_CMD, 0, "");
