2320	// trailing bytes don't get misparsed as the start of a new command. Two
2321	// give-up conditions, whichever comes first (PR #27 review point 6):
2322	//   - idle: no bytes at all for kIdleTimeoutMs
2323	//   - absolute: kAbsoluteTimeoutMs total, from when draining started,
2324	//     regardless of how many times the idle deadline got reset
2325	// The idle-only bound let a sender pacing bytes just under it keep this call
2326	// "making progress" indefinitely, blocking loop() for minutes over a single
2327	// rejected upload. This is purely resync after a decision that's already
2328	// been made (the command was already rejected), nothing is being preserved,
2329	// so there's no reason to tolerate an unbounded drain the way a real
2330	// transfer's own idle-reset deadline legitimately does.
2331	void CommandProcessor::drainBulkData(uint32_t remaining) {
2332	  static constexpr uint32_t kIdleTimeoutMs     = 5000UL;
2333	  static constexpr uint32_t kAbsoluteTimeoutMs = 15000UL;
2334	  uint8_t buf[256];
2335	  uint32_t start = millis();
2336	  uint32_t t0 = start;
2337	  while (remaining > 0) {
2338	    if ((uint32_t)(millis() - start) > kAbsoluteTimeoutMs) break;
2339	    size_t want = (remaining < sizeof(buf)) ? (size_t)remaining : sizeof(buf);
2340	    size_t got = current_source_->readBulkBytes(buf, want);
2341	    if (got > 0) {
2342	      remaining -= (uint32_t)got;
2343	      t0 = millis();
2344	    } else {
2345	      if ((uint32_t)(millis() - t0) > kIdleTimeoutMs) break;
2346	      yield();
2347	    }
2348	  }
2349	}
