2352	// handleGetSdArchive: 0x8A, arms a full-SD-content ZIP (store mode) stream.
2353	// Sends a bulk-read response header (8-byte uint64 LE total size) here,
2354	// synchronously (entry collection only stats files, open+size+close; it
2355	// never calls sendRaw() and can't stall a transport). The ZIP bytes
2356	// themselves (headers, file data, data descriptors, central directory,
2357	// EOCD) are streamed asynchronously afterward by serviceArchive(), one
2358	// bounded sendRaw() per loop() call; see the ar_* fields' comment in
2359	// CommandProcessor.h for why (PR #27 review point 2).
2360	//
2361	// ZIP uses data descriptors (flags=0x0008) so CRC/sizes are deferred — the
2362	// total size can be computed before streaming any file data.
2363	// ---------------------------------------------------------------------------
2364	
2365	void CommandProcessor::handleGetSdArchive() {
2366	  uint16_t entry_count = 0;
2367	
2368	  // --- Collect root manifest files ---
2369	  static const char *const kRootFiles[] = { "MANIFEST.bin", "MANIFEST.txt" };
2370	  for (uint8_t i = 0; i < 2; ++i) {
2371	    ZipEntry &e = ar_entries_[entry_count];
2372	    e.name_len = (uint8_t)strlen(kRootFiles[i]);
2373	    memcpy(e.zip_name, kRootFiles[i], e.name_len + 1);
2374	    snprintf(e.sd_path, sizeof(e.sd_path), "/%s", kRootFiles[i]);
2375	    File f = SD.open(e.sd_path, FILE_READ);
2376	    if (!f) continue;
2377	    e.file_size = (uint32_t)f.size();
2378	    f.close();
2379	    e.crc32 = 0;
2380	    e.lhf_offset = 0;
2381	    ++entry_count;
2382	  }
2383	
2384	  // --- Collect pattern files ---
2385	  uint16_t pc = sd_.patternCount();
2386	  for (uint16_t i = 1; i <= pc && entry_count < kArchiveMaxEntries; ++i) {
2387	    const char *name = sd_.patternName(i);
2388	    if (!name) continue;
2389	    ZipEntry &e = ar_entries_[entry_count];
2390	    snprintf(e.zip_name, sizeof(e.zip_name), "patterns/%s", name);
2391	    e.name_len = (uint8_t)strlen(e.zip_name);
2392	    snprintf(e.sd_path, sizeof(e.sd_path), "%s/%s", AC::constants::pattern_dir, name);
2393	    File f = SD.open(e.sd_path, FILE_READ);
2394	    if (!f) continue;
2395	    e.file_size = (uint32_t)f.size();
2396	    f.close();
2397	    e.crc32 = 0;
2398	    e.lhf_offset = 0;
2399	    ++entry_count;
2400	  }
2401	
2402	  // --- Pre-compute total ZIP size and per-entry LFH offsets ---
2403	  // Each entry: LFH(30+nlen) + data(file_size) + DataDescriptor(16)
2404	  // Central directory: sum of (46+nlen) per entry
2405	  // EOCD: 22 bytes
2406	  uint32_t offset  = 0;
2407	  uint32_t cd_size = 0;
2408	  for (uint16_t i = 0; i < entry_count; ++i) {
2409	    ar_entries_[i].lhf_offset = offset;
2410	    offset  += 30u + ar_entries_[i].name_len + ar_entries_[i].file_size + 16u;
2411	    cd_size += 46u + ar_entries_[i].name_len;
2412	  }
2413	  uint32_t cd_offset  = offset;
2414	  uint64_t total_size = (uint64_t)cd_offset + cd_size + 22u;
2415	
2416	  // --- Send bulk response header (8-byte uint64 LE size, then raw ZIP) ---
2417	  uint8_t size_buf[8] = {};
2418	  memcpy(size_buf, &total_size, sizeof(total_size));
2419	  current_source_->sendResponse(GET_SD_ARCHIVE_CMD, 0, size_buf, sizeof(size_buf));
2420	
2421	  // --- Arm the async stream; serviceArchive() sends the ZIP body from loop() ---
2422	  ar_entry_count_ = entry_count;
2423	  ar_entry_idx_    = 0;
2424	  // Empty library (blank/absent SD): the promised total_size is the 22-byte
2425	  // EOCD alone. Arm straight into kEocd — kLocalHeader and kCentralDir both
2426	  // dereference ar_entries_[ar_entry_idx_] before any bound check, so
2427	  // entering either with entry_count == 0 streams a garbage (or stale, since
2428	  // ar_entries_ persists across archives) entry against that promise.
2429	  ar_phase_        = (entry_count == 0) ? ArchivePhase::kEocd
2430	                                        : ArchivePhase::kLocalHeader;
2431	  ar_cd_offset_    = cd_offset;
2432	  ar_cd_size_      = cd_size;
2433	  ar_source_       = current_source_;
2434	  ar_deadline_     = millis() + kArchiveIdleTimeoutMs;
2435	  ar_active_       = true;
2436	
